      "tweetId" : "2018248316908433472",
      "fullText" : "很久没有针对某个链上项目单独写一篇推文了，但近期的Moltbook让我觉得有机会成为引领新一轮链上AI Meta的龙头。前两天上涨过快，我也不想引发过度Fomo，正好趁着现在大回调，发文介绍一下。\n\n@moltbook 是基于 @openclaw… https://t.co/K6Yp3JpB9y",
