      "fullText" : "生活，本就是一场寻找乐趣的旅行。在忙碌与平凡中，不妨放慢脚步，聆听花开的声音，品尝简单的美食，或与三两好友笑谈风云。乐趣，不在于远方，而在当下的每一刻，用心感受，生活处处皆风景。",
